function setup() {
  createCanvas(WIDTH, HEIGHT, WEBGL);
  brush.scaleBrushes(2);

  // Draw stars
  for (let i = 0; i < 50; i++) {
    let x = random(0, width);
    let y = random(0, height * 0.2);
    stars.push({ x, y, size: random(5, 10) });
  }

  // Draw mountains
  const mountainHeight = 100;
  for (let i = 0; i < 10; i++) {
    let x = i * 100;
    let y = mountainHeight + i * 50;
    mountains.push({ x, y });
  }
}

// Draw function
function draw() {
  translate(-WIDTH / 2, -HEIGHT / 2);
  background("#f4efe4");

  // Draw stars
  for (let star of stars) {
    brush.circle(star.x, star.y, star.size);
  }

  // Draw mountains
  noStroke();
  for (let mountain of mountains) {
    brush.stroke("#7eb48f");
    brush.line(mountain.x - 50, mountain.y - mountainHeight, mountain.x + 50, mountain.y - mountainHeight);
  }

  // Draw sunset
  noStroke();
  brush.fill("#ffcc33"); // Orange color for sunset
  brush.circle(200, 300, 200); // Medium-sized circle for the middle sunset

  // Add small circles in the foreground for detail
  for (let i = 0; i < 30; i++) {
    let x = random(50, 350);
    let y = random(100, 250);
    brush.circle(x, y, 10);
  }
}

