  const radius = min(width, height) * 0.3; // Half the width or height
  push();
  translate(centerX, centerY);
  rotate(frameCount / 100); // Rotate the sun slightly with time
  fill("#ffcc00"); // Yellow color
  circle(0, 0, radius);
  pop();
}

