function paintHills(color) {
  const hillRadius = min(width, height) * 0.4; // Small hills in the foreground
  const hillGap = hillRadius * 0.3; // Space between hills

  for (let i = 0; i < height / hillGap; i++) {
    push();
    translate(width / 2, i * hillGap);
    noStroke();
    fill(color);
    for (let j = 0; j < width; j += hillRadius + hillGap) {
      ellipse(j, 0, hillRadius);
    }
    pop();
  }

  push();
  translate(width / 2, ((height / hillGap) - 1) * hillGap);
  fill(color);
  for (let j = 0; j < width; j += hillRadius + hillGap) {
    ellipse(j, 0, hillRadius);
  }
  pop();
}

