function draw() {
  translate(-width / 2, -height / 2);
  background("#a8dadc"); // green hill

  // Sunset gradient from yellow to orange to red
  for (let y = 0; y < height; y++) {
    let a = map(y, 0, height, 0, 255); // alpha gradient
    let red = map(y, 0, height, 255, 200); // orange component
    let green = map(y, 0, height, 0, 50); // green component
    let blue = map(y, 0, height, 255, 0); // red component

    push();
    colorMode(HSB, 360, 100, 100);
    fill(red, green, blue, a);
    strokeWeight(2);
    line(0, y, width, y);
    pop();
  }

  // Hills effect using circles
  for (let x = 0; x <= width; x += 50) {
    let startRadius = 50 + sin(radians(x)) * 50;
    let endRadius = 50 + cos(radians(x)) * 50;

    push();
    colorMode(HSL, 180, 80, 80);
    fill(random(0, 360), 50, 100);
    noStroke();
    circle(x, height / 2, startRadius);
    endShape(false);
    circle(x, height / 2, endRadius);
    pop();
  }
}

