  brush.strokeWeight(5);
  brush.noSmooth();
  for(let j=30;j<=350;j+=15){
    for(let k=15;k<=175;k+=15){
      brush.rect(k-5,j,10,10,10);
      brush.circle(j,k,5);
    }
  }

  brush.line(5,400,295,300);
  brush.fill("#ff7700");
  brush circle(150,200,50);
} 

function randomColor(count){
  return "#"+(Math.floor(Math.random()*256)).toString(16)+(Math.floor(Math.random()*256)).toString(16)+ (Math.floor(Math.random()*256)).toString(16);
} 

function randBetween(a, b) {
  var c = Math.random();
  return a + c * (b - a);
}

