// Fill gradient function to interpolate between two colors and return shades in between
function fillGradient(start, stop, count, bg = '#f4efe4') {
  const colorArray = [];
  const minVal = Color.red(stop) + Color.green(stop) + Color.blue(stop);
  const maxVal = Color.red(start) + Color.green(start) + Color.blue(start);
  let range = maxVal - minVal;

  if(count > 1 && range != 0){
    const diff = range/(count-1);

    for(let i=0;i<count;i++){
      const colorIndex = Math.floor((i*diff)+minVal);
      const red = round(Color.red(colorIndex));
      const green = round(Color.green(colorIndex));
      const blue = round(Color.blue(colorIndex));

      colorArray.push(`rgb(${red}, ${green}, ${blue})`);
    }
  }else{
    colorArray.push(stop);
  }

  return colorArray;
}

