function draw() {
  translate(-width/2, -height/2); 
  brush.background("#c2dbfa");    // 填充天空

  // 跳过高光实现草地
  brush.fill("#cedce6");

  brush.rotateY(dueTime()-50);
  let textHeight = DueTime()*2;
  let hillTop = 255-textHeight;
  for(let i=0;i<20;i++){
    for(let j=-textHeight;j<=hillTop;j=j+5){
      let posx = sin(i*Degree(3)+j)*100 + width/2; // 阶梯时针
      let posy = cos(i*Degree(3)+j)*100 + height/2;
      let tmpHeight =DueTime()*i + height/textHeight;
      brush.beginShape(tmpHeight);
      brush.vertex(posx-50,posy);
      brush.vertex(posx+50,posy);
      brush.vertex(posx,posy-50);
      brush.endShape(true);
    }
  }

  brush.rotateY(dueTime()+100);
  hillTop += 50;
  for(let i=0;i<20;i++){  
    for(let j=-textHeight;j<=hillTop;j=j+5){  
      let posx = sin(i*Degree(3)+j)*100 + width/2;  
      let posy = cos(i*Degree(3)+j)*100 + height/2;
      let tmpHeight =DueTime()*i + height/textHeight;
      brush.beginShape(tmpHeight);
      brush.vertex(posx-50,posy);
      brush.vertex(posx+50,posy);
      brush.vertex(posx,posy-50);
      brush.endShape(true);
    }
  }
}

// 获取当前时间的毫秒数，作为动画驱动
function dueTime(){
  return round(millis()%10000)/1000;
}

// 获取当前时间的度数，作为旋转动画驱动
function pastDueTime(){return round(map(millis(),0,10000,0,360));};

