  translate(-width / 2, -height / 2);
  background("#ecbfe4"); // Light greens
  brush.noStroke();

  // Sunny day colors
  brush.fill("#ffd1c5", 255); // Bright yellow (sky)
  brush.fill("#cc4e4b", 255); // Coral shades

  // Add morning mist
  brush.noFill();
  brush.circle(width / 2, height / 3, 40);
  brush.fillStyle("rgba(255, 255, 255, 0.5)");
  brush.strokeColor("rgba(255, 255, 255, 0.5)");

  // Hills - smooth gradients
  brush.beginShape(0.15);
  brush.vertex(0, height / 2 - 200);
  brush.vertex(400, height / 2 - 200);
  brush.vertex(400, height / 2);
  brush.vertex(0, height / 2);
  brush.endShape(true);

  // Evening clouds - merged circles for contrast
  brush.beginShape(0.4);
  brush.circle(width / 2 - 10, height / 2 + 100, 50);
  brush.circle(width / 2 + 10, height / 2 + 100, 50);
  brush.endShape(true);

  // Sunset glow
  brush.noFill();
  brush.beginShape(0.5);
  brush.vertex(width / 2 - 100, height / 2);
  brush.vertex(width / 2 + 100, height / 2);
  brush.vertex(width / 2, height / 2 + 300);
  brush.endShape(true);

  // Roses (final touch)
  brush.beginPath();
  brush.moveTo(100, 100);
  brush.lineTo(140, 140);
  brush.lineTo(120, 220);
  brush.lineTo(200, 180);
  brush.lineTo(250, 100);
  brush.lineCap = 'round';
  brush.strokeStyle('#da3383');
  brush.fill('rgba(218, 51, 131, 1)');
  brush.strokeWeight(10);
  brush.lineWidth = 10;
  brush.strokeCap = 'square';
  brush.closePath();
}

