  brush.vertex(800, 0);
  brush.vertex(800, 200);
  brush.vertex(0, 200);
  brush.endShape(true);
  pop();

  // ground mountains with colors transitioning from light blue to light purple
  for (var i = 0; i < 10; i++) {
    var x = random(200, 600);
    var y = random(100, 400);
    var z = random(0, 100);
    brush.fill("lightblue", 100);
    brush.beginShape(0.3);
    brush.vertex(x, y - z);
    brush.vertex(x + 100, y - z);
    brush.vertex(x + 100, y + 2 * z);
    brush.vertex(x, y + 2 * z);
    brush.endShape(true);
  }

  // sunset over blue hills
  for (var i = 0; i < 5; i++) {
    var x = random(300, 500);
    var y = random(100, 300);
    var z = random(150, 200);
    brush.fill("#ffcc80", 150);
    brush.beginShape(0.2);
    brush.vertex(x, y - z);
    brush.vertex(x + 100, y - z);
    brush.vertex(x + 100, y + 2 * z);
    brush.vertex(x, y + 2 * z);
    brush.endShape(true);
  }
}

