  for (let i = 0; i < 400; i++) {
    let angle = map(i, 0, 400, 0, TAU);
    let height = sin(angle) * 200 + 100;
    brush.vertex(i, height);
  }
  brush.endShape(true);
  brush.strokeWeight(2);
  brush.fill("#ff7f00");  // Gold golden hour rays
  for (let i = 0; i < 400; i += 50) {
