function draw() {
  translate(-width / 2, -height / 2);
  background("#c8eae8");

  // drawing green hills

  var hillHeight = random(100, 200); // Hill height
  var hillWidth = random(200, 400); // Hill width
  for (var i = 0; i < hillHeight * 2; i += 20) {
    if (i % 4 === 0) {
      var elevationFactor = sin(i / 200.0 * PI); // Elevation variation
      var greenColor = map(elevationFactor, -1, 1, 0, 1); // Green intensity
      brush.noFill();
      brush.stroke(0, 0, greenColor * 255, 128);
      brush.beginShape(0.7);
      brush.vertex(-hillWidth, 0);
      brush.vertex(0, 0);
      brush.vertex(hillWidth, 0);
      brush.endShape(true);
    } else {
      brush.beginShape(0.7);
      brush.vertex(-hillWidth, i);
      brush.vertex(-hillWidth + 100, i - 200);
      brush.vertex(hillWidth - 100, i - 200);
      brush.endShape(true);
    }
  }

  // painting towards sunset

  var sunsetRadius = 150;
  var sunsetDistance = 200;
  for (var x = -sunsetDistance; x <= sunsetDistance; x++) {
    var y = Math.sqrt(sunsetRadius * sunsetRadius - x * x);
    brush.noFill();
    brush.stroke("#ff9166", 128);
    brush.beginShape(0.7);
    brush.vertex(x, y);
    brush.vertex(x + 50, y + 50);
    brush.vertex(x - 50, y + 50);
    brush.endShape(true);
  }
}

