  for (let i = 0; i < 5; i++) {
    let x = width / 2 + cos(radians(i * 45)) * 200;
    let y = height / 2 + sin(radians(i * 45)) * 200;
    let w = sin(radians(i * 45)) * 100;
    let h = cos(radians(i * 45)) * 100;
    brush.beginShape(0.2);
    brush.vertex(x, y - h / 2);
    brush.vertex(x - w / 2, y - h / 2);
    brush.vertex(x - w / 2, y + h / 2);
    brush.vertex(x, y + h / 2);
