var time = 0;

function update(time) {
  var offset = map(noise(time), 0, 1, 0, 2 * PI);
  var scale = 0.3 + map(noise(time + 100), 0, 1, 0, 0.1);
  brush.circle(200 + sin(offset) * 100, 100 + cos(offset) * 100, 100 + scale * 50);

  time += 0.01;
}

function loop() {
  update(frameCount / 60);
}

