      map(cos(i/4), -1, 1, 255, 0),
      map(tan(i/5), -1, 1, 255, 0),
      255
    );
    brush.fill(color, 255);
    brush.circle(map(cos(i/2), -1, 1, width/2-1, width/2+1), map(sin(i/3), -1, 1, height/2-1, height/2+1));
  }

  // Hills
  for(let i = 0; i < 360; i++){
    let color = color(0, map(sin(i/3), -1, 1, 255, 0), map(cos(i/4), -1, 1, 255, 0), 255);
    brush.fill(color, 200);
    brush.beginShape(0.3);
    brush.vertex(width/2-1, i*10);
    brush.vertex(i*10, i*10);
    brush.vertex(i*10-1, i*20);
    brush.endShape(true);
  }
}

