function draw() {
  translate(-width / 2, -height / 2);
  background("#ece9de");

  // Sky
  for(let i = 20; i < 400; i+=50){
    let angle = map(i, 20, 400, 0, TWO_PI);
    let color = hueToRGB(angle * 3, 500, 150, 255); // HSB Hue 0-360 Saturation 0-100 Brightness 0-255
    brush.noStroke();
    brush.fill(color, 190);
    brush.beginShape(0.4);
    brush.vertex(i, 0);
    brush.vertex(i, height);
    brush.endShape(true);
  }

  // Hills
  for(let i = 80; i < 250; i +=5){
    let yPos = map(i, 80, 250, 0, height/4);
    brush.noStroke();
    brush.fillTexture(0.3, 0.5);
    brush.fill("#83ef99", 160);
    brush.beginShape(0.3);
    brush.vertex(i, yPos);
    brush.vertex(i, yPos+10);
    brush.vertex(width, yPos+10);
    brush.vertex(width, yPos);
    brush.endShape(true);
  }

  // Sunset glow
  for(let i = 100; i < 400; i+=5){
    let r = map(i, 100, 400, 20, 60);
    let angle = map(i, 100, 400, 0, TWO_PI);
    let color = hueToRGB(angle * 3, 250, 100, 255);
    brush.noStroke();
    brush.fill(color, 20);
    brush.beginShape(0.5);
    brush.vertex(i-r, height);
    brush.vertex(i+r, height);
    brush.vertex(i+r, yPos);
    brush.vertex(i-r, yPos);
    brush.endShape(true);
  }

  // Ground
  brush.noStroke();
  brush.fill("#b2e48c", 240);
  brush.circle(width/2, height/2, width/1.5);
}

