function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4"); // Light blue sky

  // Sunlight
  stroke("#ffcc00");
  strokeWeight(10);
  line(200, 200, 250, 150); // Sun's rays
  fill("#ffcc00");

  // Clouds
  push();
  noStroke();
  fill("#fffacd");
  ellipse(180, 30, 100, 50); // Top right cloud
  ellipse(260, 20, 120, 60); // Bottom left cloud
  pop();

  // Hills
  push();
  noStroke();
  fill("#008b8b"); // Green color
  surfaceBegin(100, 150); // Start the surfacing
  surfaceSetAlpha(0.5); // Set alpha value
  for (let y = 0; y < height; y += 10) {
    brush.fill("#008b8b");
    brush.beginShape(0.3);
    brush.vertex(y, 150);
    brush.vertex(height - y, 150);
    brush.vertex(width, 225);
    brush.vertex(y, 225);
    brush.endShape(true);
  }
  surfaceEnd(); // End the surfacing
  pop();

  // Descend to the ground
  translate(0, -100);
  brush.beginShape(0.3);
  brush.vertex(0, 225);
  brush.vertex(400, 225);
  brush.vertex(400, 350);
  brush.vertex(0, 350);
  brush.endShape(true);

  // Trees
  push();
  noStroke();
  fill("#006b35");
  brush.fill("#6b8e23");
  for (let i = 0; i < 8; i++) {
    let x = random(0, width);
    let height = random(150, 250);
    brush.beginShape(0.3);
    brush.vertex(x, 225 + height);
    brush.vertex(x + 50, 225 + height);
    brush.vertex(x + 50, 275 + height);
    brush.vertex(x, 275 + height);
    brush.endShape(true);
  }
  pop();
}

