function draw() {
  translate(-width / 2, -height / 2);
  background("#f9d9aa");    // Light yellow shades for sunset
  stroke("#0000ff");       // Black color for the hills
  fill("green");             

  // Drawing grass hills
  for (let i = 0; i < 8; i++) {
    let hillWidth = random(100, 200);
    let hillHeight = random(100, 200);
    push();              // Save the current transformation state
    strokeWeight(random(1, 5)); 
    translate(i * hillWidth + random(-50, 50), height/2 - hillHeight);
    stroke(random(0, 10));
    fillGradient("#6b8e23", "#00bb22");  // Gradient color fades from green to light green
    rectMode(CENTER);  
    rect(0, 0, hillWidth, hillHeight);
    pop();             // Restore the previous transformation state
  }

  // Adding the sunset effect
  stroke("#ff0000");
  strokeWeight(5);
  for (let i = 0; i < 10; i++) {   // Number of rays
    let angle = map(i, 0, 9, 0, TAU / 2);
    let x = 200 + 50 * cos(angle);
    let y = 200 - 50 * sin(angle);
    line(200, 200, x, y);
  }
}

