function draw() {
  translate(-width / 2, -height / 2);
  background("#043546"); // Green hue
  brush.noStroke();
  brush.fill("#ffd1cc", 240); // Yellow-tan color

  // Hills (from coast to mountain top)
  for(let i = 0; i < 20; i++) {
    let w = map(i, 0, 19, 40, 200); // Width of hills
    let h = random(20, 40); // Height of hills
    brush.fill("#fbcaca", 160); // Buffer color
    brush.beginShape(0.5);
    brush.vertex(0, height - h);
    brush.vertex(w * cos(PI / 3), height - h - 100 + h);
    brush.vertex(w * cos(5 * PI / 6), height - h - 100 + h);
    brush.endShape(true);
    brush.fillTexture(0.4, 0.4); // Fill texture color
    brush.circle(map(i, 0, 19, 140, 260), 220); // Red dot at the center of hill
  }

  // Sunset behind hills
  brush.stroke("#ff0000", 255); // Red sun set color
  brush.strokeWeight(5);
  brush.line(width / 2, 0, width / 2, height);

  // Colorful line to pass through all mountain peaks
  for(let j = 0; j <= 8; j++) {
    let dy = sin(j * (PI / 4)) * 150;
    brush.line(width / 2 - j * 150, height - j * dy, width / 2 + j * 150, height - j * dy);
  }
}

