function draw() {
  translate(-width / 2, -height / 2);
  const x = 200;   // hill center X
  const y = 300;   // hill center Y
  const radius = 100; // hill radius

  brush.noStroke();
  brush.fill("green", 180);
  brush.beginShape(0.4);
  brush.vertex(0, 0);
  brush.vertex(width, 0);
  brush.circle(x, y, radius * 1.5);
  brush.endShape(true);

  brush.fill("#ff0000", 160);
  brush.beginShape(0.5);
  brush.vertex(0, 0);
  brush.vertex(width, 0);
  brush.beginShape(0.5);
  brush.translate(x, y);
  brush.rotate(90); // Sunset light
  brush.vertex(-radius * 1.5, height - radius * 1.5);
  brush.vertex(radius * 1.5, height - radius * 1.5);
  brushvertex(radius * 1.5, -height + radius * 1.5);
  brush.vertex(-radius * 1.5, -height + radius * 1.5);
  brush.endShape(true);

  brush.fill("black", 100);
  brush.beginShape(0.5);
  brush.translate(x, y);
  brush.rotate(90); // Sunset glow
  brush.vertex(-radius * 1.5, height - radius * 1.5);
  brush.vertex(radius * 1.5, height - radius * 1.5);
  brushvertex(radius * 1.5, -height + radius * 1.5);
