  for (let y = 0; y <= height; y += 100) {
    let t = map(y, 0, height, 0, 1); // Time in the range [0, 1]
    let hillProgress = map(t, 0, 1, 0, hillOpacity);
    let hillFill = rgba(hillColor, hillProgress);
    brush.fill(hillFill);
    brush.circle(width/2, y, width);
  }
}

