function draw() {
  translate(-width / 2, -height / 2);
  background("#a5c41e"); // Greenish yellow

  // Paints the sky
  for(let i = 0; i < height; i += 40) {
    let h = map(i, 0, height, 0, 360);  // Hue of the light at each position
    let s = 100;                         // Saturation
    let l = 50 + sin(h * PI / 360) * 30; // Lightness (darkens over time)

    brush.noStroke();
    brush.fillTexture(0.9, 0.8);
    brush.fill(`#${l.toString().padStart(2, '0')}${s.toString().padStart(2, '0')}5a`, 180);
    brush.beginShape(0.3);
    brush.vertex(0, i);
    brush.vertex(width, i);
    brush.vertex(width, height);
    brush.vertex(0, height);
    brush.endShape(true);
  }

  // Paints the hill sides
  let gradientAmount = 5;
  for(let i = 0; i < width; i += gradientAmount) {
    let h = map(i, 0, width, 0, 360);  // Hue of the light at each position
    let s = 100;                         // Saturation

    brush.noStroke();
    brush.fillTexture(0.5, 0.3);
    brush.fill(`#${h.toString().padStart(2, '0')}${s.toString().padStart(2, '0')}b3`, 180);
    brush.beginShape(0.3);
    brush.vertex(i, 0);
    brush.vertex(i + gradientAmount, 0);
    brush.vertex(i + gradientAmount, height - 50); // Lower part of the hill
    brush.vertex(i, height - 50);
    brush.endShape(true);
  }
}

