  createCanvas(800, 600, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#007bff"); // Sky color
  brush.noStroke();
  brush.fill("#4CAF50"); // Grass color

  // Sun position
  let sunX = width * 0.5;
  let sunY = height * 0.4;

  // Sun path over grass
  for(let y = height * 0.5; y >= 0; y -= 1) {
    if(y <= sunY + 25 && y >= sunY - 25) {
      let angle = atan2(sunY - y, sunX - width * 0.5);
      let radius = abs(sunY - y) + 25;
      brush.beginShape(0.5);
      brush.fill("rgba(255, 255, 0, 0.5)");
      brush.circle(width * 0.5, y, radius);
      brush.endShape(true);
    }
  }

  // Grass patterns
  for(let y = height / 2; y < height * 0.6; y += 10) {
    for(let x = width / 2; x < width; x += 10) {
      if(x <= 150 || x >= 650) {
        brush.fill("#00aaff");
        brush.circle(x, y, 5);
      } else if(x >= 175 && x <= 625) {
        brush.fill("#00ffbf");
        brush.circle(x, y, 5);
      } else {
        brush.fill("#00ffec");
        brush.circle(x, y, 5);
      }
    }
  }

  // Sun
  brush.noStroke();
  brush.fill("#ffd700");
  brush.beginShape(0.4);
  brush.vertex(sunX, sunY - 50);
  brush.vertex(sunX, sunY - 25);
  brush.vertex(sunX - 50, sunY);
  brush.vertex(sunX + 50, sunY);
  brush.endShape(true);
}

