function draw() {
  translate(-width / 2, -height / 2);
  background("#7aaddc"); // Sunset color
  brush.stroke("#fffff"); // White for the sun

  brush.beginShape(1); // Conical curvature
  brush.vertex(200, 0);
  brush.vertex(400, 400); // Left upper corner of the hill
  brush.vertex(400, 300); // Top right corner of the hill
  brush.vertex(300, 300); // Right lower corner of the hill
  brush.vertex(300, 0); // Back
  brush.endShape();

  brush.fillTexture(0.7, 0.7); // Gradient texture for the hills
  brush.fill("#00ffcc", 180);

  // Sun center points
  var sunX = 200;
  var sunY = 300;

  // Draw a small circle for the sun center
  brush.noStroke();
  brush.fill("#ffd700"); // Golden yellow
  brush.circle(sunX, sunY, 50);

  // Draw the sun path around the circle
  brush.noFill();
  brush.strokeWeight(4);
  brush.beginShape(0.4);
  brush.vertex(sunX, sunY);
  for (var i = 0; i < 360; i += 6) { // 6 degrees per step
    var radians = radians(i);
    var x = 200 + 30 * cos(radians);
    var y = 300 + 30 * sin(radians);
    brush.vertex(x, y);
  }
  brush.endShape(true);

  // Further details can be added such as trees, grass, etc.
}

