  // Sunset
  let ltime = millis() * 0.001;
  let rtime = millis() * 0.003;

  for(let i = 0; i < width; ++i) {
    let t = map(i, 0, width, 0, TWO_PI);
    let x = sin(t + ltime) * 200 + width/2;
    let y = cos(t + ltime) * 200 + height/2;
    let c = color(255, 144, 31); // Red
    c.setAlpha(sin(rtime) * 200);
    fill(c);
    circle(x, y, 2);
  }

  // Hills
  let rainfall = noise(0.5);
  for(let i = 0; i < width; ++i) {
    let t = map(i, 0, width, 0, TWO_PI);
    let x = i - rainfall * 200;
    let y = sin(t) * 300 + height/2 - 200;
    fill("green");
    circle(x, y, 2);
  }
}

