  fill("#ffc1c9");  // Sunset
  ellipse(width / 2, 350, 80, 80);

  push();
  let sunY = 350;
  for (let i = 1; i <= 10; i++) {
    sunY -= 2;
    let sunX = width / 2 + sin(i * map(sunY, 330, 400, -PI, PI)) * 20;
    ellipse(sunX, sunY, 10, 10);
  }
  pop();
}

