}

function draw() {
  translate(-width / 2, -height / 2);
  background(GREEN_GRASS_COLOR);
  brush.noStroke();
  brush.noFill();

  // Draw hills in gradient color
  const hillStartY = height / 2;
  const hillGradient = new Easing.Quadratic.Out(ease => (hillStartY - height * ease) / hillStartY);
  for (let x = 0; x <= width; x++) {
    const grassDepth = sin(0.05 * x + frameCount) * 0.1;
    const y = grassDepth;
    if (y < height) {
      fill(BGRColor(SUNSET_HUE));
      strokeWeight(0.1);
      brush.circle(x, y - grassDepth / 1.5, 5);
    }
  }

  // Draw sun
  const SunY = grassDepth;
  if (SunY > height * 0.75) {
    fill(BGRColor(SUNSET_HUE));
    const maskSize = map(SunY - height * 0.75, 0, height - height * 0.75, 20, 50);
    const maskBeginY = map(SunY - height * 0.75, 0, height - height * 0.75, 0, 45);
    brush.noStroke();
    brush.alpha(maskSize);
    brush.beginShape(0.9);
    brush.vertex(200, SunY);
    brush.vertex(210, SunY + 30);
    brush.vertex(215, SunY + 20);
    brush.vertex(220, SunY + 30);
    brush.endShape(true);
  }

  // Move the camera up
  rotateY(0.01);
}

