  brush.fill("white");
  brush.fillTexture(0.2, 0.4);
  brush.circle(width/2, height/2+20, 25);
  pop();

  // Coastline
  push(); // Layer 4
  brush.noStroke();
  brush.fill("#adca7a");
  brush.fillTexture(0.6, 0.4);
  brush.circle(0, height/2, 60);
  brush.circle(width, height/2, 60);
