function draw() {
  translate(-width / 2, -height / 2);
  background("green");
  fill("#ffd7aa");   // sunset
  shape(new CanvasSketch(() => {
    const size = Math.min(width, height) * 0.2;
    let p = new Circle((size/10)*Math.random(), (size/10)*Math.random());

    function update() {
      p.x = random(0, width);
      p.y = random(0, height);
    }

    const noise = new SimplexNoise();

    return {
      render: () => {
        background("green");

        stroke("#ffd7aa");
        strokeWeight(4);

        for (let i = 0; i < 200; i++) {
          const angle = map(noise.noise(p.x/40, p.y/40), 0, 1, 0, 360);
          push();
            translate(p.x, p.y);
            rotate(angle);
            circle(0, 0, 40);
          pop();

          update();
        }
      }
    };
  }, { antialias: true }));

  fill("#ffd7aa"); 
  noStroke();
  for (let i = 0; i < 2; i++) {
    beginShape();
    translate(random(50), random(50));
    vertex(0, 0);
    vertex(width, 0);
    vertex(width, height);
    vertex(0, height);
    endShape(true);
    fillTexture(0.5);
  }
}

