    let amplitude = 100;
    let speed = 1;
    let offset = map(cos(t), -1, 1, 0, 400); // Offset varies with time to create waves
    const t2 = i % 2; // Half-cycle for the second half of each row
    brush.circle(r, amplitude + offset + (t2 == 0 ? sin(t) : cos(t)) * w, r + 1);
  });
}

function setup() {
