function draw() {
  translate(-width / 2, -height / 2);
  clear();
  background("green");

  // calculate sunset sky
  const sunrise = (colorMode().hue / 360) * 0.2;   // simulate sunset early in the morning
  const sunsetRadial = sin(radians(sunrise)) * map(sunrise, 0.0, 1.0, 50, 250); // radial distance from center during sunset

  // draw sun dome
  let innerRadius = map(sunsetRadial, 50, 250, 10, 80);
  let outerRadius = map(sunsetRadial, 50, 250, 40, 70);
  let angle = 0;
  const numSeams = 6;
  const sunlightAmount = 20;

  for (let j = 0; j < numSeams; j++) {
    angle = PI / 4 * (j + 0.5);
    stroke(0, 360, 100, sunlightAmount); // sunlight color
    brush.stroke('#ffffff');
    brush.scaleBrush(2.0);
    brush.beginShape(angle);
    brush.circle(200, 200, innerRadius); // inner circle of the dome
    brush.circle(200, 200, outerRadius); // outer circle of the dome
    brush.endShape(false);
  }

  // draw hills
  stroke('lightgray');  // hill lines
  brush.lineWidth(5);
  noFill();
  let stepSize = map(sin(radians(sunsetRadial)), 0, 1.0, 100, 250);
  let numHills = 50;

  for (let i = 0; i < numHills; i++) {
    let locationX = random(-50, 50);
    let locationY = map(random(-50, 50), -50, 50, 150, 450);
    brush.noStroke();
    brush.beginShape();
    brush.vertex(locationX, locationY);
    brush.vertex(locationX - stepSize, locationY + 10);
    brush.vertex(locationX + stepSize, locationY + 10);
    brush.vertex(locationX, locationY + 5);
    brush.endShape(false);
  }
}

