// Sketch function
function sketch(size) {
    const numberOfLayers = 3;

    // Paint grays
    size({
        type: 'color',
        mode: 'linear',
        attr: 'sky',
        min: '#72aa63', 
        max: '#f4efe4', 
        num: numberOfLayers * 10
    });

    // Paint a layer for the clouds
    size({
        type: 'cloud',
        speed: [0.2, -0.2],
        count: 100,
        lines: 10,
        maxLen: 20,
        maxCount: 20,
        textureRate: 0.8,
        smooth: false,
        randomOffset: true
    });

    // Paint a layer for the grass
    size({
        type: 'color',
        mode: 'linear',
        attr: 'grass',
        min: '#00ff7f', 
        max: '#00cc00',
        num: numberOfLayers * 10
    });

    // Paint a layer for the sunset
    size({
        type: 'blur',
        num: 20,
        direction: random(-2.0, 2.0),
        iterations: 2,
        repeatMode: 'clamp'
    });

    // Paint a layer for the mountains and painting line
    size({
        type: 'color',
        mode: 'linear',
        attr: 'mountains',
        min: "#c46a00", 
        max: "#893600",
        num: numberOfLayers * 10,
    });

    // Paint lines in the landscape
    size({
        type: 'line',
        maxLength: 3,
        length: 50,
        angle: PI/2,
        distance: 200,
        fill: 200
    });
}

