      brush.circle(x, y, ellipseRadius);
    }
    else{
      brush.beginShape(0.3);
      brush.vertex(0, height);
      brush.vertex(width/2, height-r);
      brush.vertex(width, height);
      brush.endShape(true);
    }
  }

  brush.stroke("#4d7720"); 
  brush.strokeWeight(12); 
  brush.noFill();

  brush.circle(200, 100, 160); 

  brush.fill("#ffc98e"); 

  for(let j = 0; j < 5; j++){
    brush.fill("#ffcdac");
