  let sunX = width / 2;
  let sunY = height * 0.4;

  // Color of the sky below the sun (takes influence from the sunset color)
  let skyBelowSunColor = color(sunColor);

  // Sky color above the sun
  let skyAboveSunColor = color(fxaa_adjuster(skyBelowSunColor));

  // Painting goes here

  // Create sun shading effect
  for (let x = sunX; x < width; x += 10) {
    let y = map(abs(noise(x / 5 + sunY / 10)), -1, 1, height * 0.8, height);
    let radius = noise(x / 5 - sunY / 10) * 20;
    let offsetY = (y - sunY) / 20;
    let color = color(fxaa_adjuster(cos(mouseX / 50) * offsetX, sin(mouseX / 50) * offsetX));
    stroke(color);
    noFill();
    ellipse(x, y, radius * 2);
  }

  // Painting more details here
  // ...
}

// Function to adjust opacity
function fxaa_adjuster(value, amount = 0.1) {
  value = pow(value + amount, 4) - amount;
  return map(value, 0, 1, 0, 255);
}

