        brush.vertex(x, altitude);
        brush.vertex(x + hillsScale * height, altitude);
        brush.vertex(x + hillsScale * height, altitude + hillsScale * height);
        brush.vertex(x, altitude + hillsScale * height);
        brush.endShape(true);
      }
    }
  }

  brush.fill("#ff6e4c", 180); // crimson sunset horizon
  brush.circle(width / 2, 200, 250);
}

