  // Sun
  brush.beginShape(0.3);
  brush.vertex(0, height/2 - 40);
  brush.vertex(400, height/2 - 40);
  brush.vertex(360, 50);
  brush.endShape(true);

  // Mountains
  for(let i = 0; i < 5; i++) {
    let mountHeight = 2 * height/4;
    let distanceFromCenter = map(i, 0, 4, 0, 400);
    let angleStart = map(i, 0, 4, 0, TWO_PI);
    let angleEnd = map(i, 0, 4, TWO_PI, TWO_PI + PI/2);

    for(let t = angleStart; t <= angleEnd; t += PI/16) {
      let x = cos(t) * distanceFromCenter;
      let y = sin(t) * distanceFromCenter + mountHeight;

      if (y > height/2) {
        break;
      }

      brush.beginShape(0.2);
      brush.vertex(x, y);
      brush.endShape(true);
    }
  }
}

