  background("#66ccff"); // Sky color
  brush.noStroke();
  brush.fill("#00cccc"); // Grass hue
  brush.beginShape(0.7); // Weave pattern for hills
  let step = width / 20;
  for (let x = step; x < width - step; x += step * 2) {
    brush.vertex(x, height);
    brush.vertex(x + step, height - sin(radians(x)) * 200);
  }
  brush.endShape(true);
  brush.noStroke();
  brush.fill("#ffeabf"); // Light orange color for sun
  brush.beginShape(0.5); // Ring pattern for sun around the horizon
  brush.noFill();
  for (let rad = 0; rad <= TWO_PI; rad += PI / 6) {
    brush.fill("#ffffff"); // White circle with darker edges
    brush.beginShape(0.2);
    brush.noStroke();
    brush.vertex(width / 2 + cos(rad) * 60, height / 2 + sin(rad) * 60);
    brush.vertex(width / 2 + cos(rad - PI / 6) * 80, height / 2 + sin(rad - PI / 6) * 80);
    brush.vertex(width / 2 + cos(rad + PI / 6) * 80, height / 2 + sin(rad + PI / 6) * 80);
    brush.endShape(true);
  }
}

