class BrickWall extends BrickBuilder {
  constructor(wallWidth, wallHeight) {
    super(wallWidth, wallHeight);
    bricksRowHeight = wallHeight / brickRows;
    brickSideLength = wallWidth / rows;
  }

  buildBricks() {
    let gridX = 0;
    for (let row = 0; row < brickRows; row++) {
      let offsetY = 0;
      for (let col = 0; col < rows; col++) {
        let brickColor = '#0096cb'; // blue brick color
        let brickSize = brickSideLength;
        let x = col * brickSize;
        let y = row * bricksRowHeight + offsetY;
        brickRenderer(x, y, brickSize, brickSize, brickColor);
      }
      offsetY += bricksRowHeight;
    }
  }
}

class BrickRenderer {
  constructor(x, y, width, height, color) {
    // add a smaller rectangle texture on top of the larger brick
    const baseSize = Math.min(width, height);
    baseRectangle.baseColor = '#FFFFFF';
    baseRectangle.width = baseSize;
    baseRectangle.height = baseSize;

    const textureSize = 256;
    const textureCoordinates = [
      [0, 0], [textureSize, 0], [textureSize, textureSize], [0, textureSize]
    ];
    baseRectangle.texture = textureCoordinates;

    baseRectangle.x = x;
    baseRectangle.y = y;
    baseRectangle.renderer(this);
  }

  renderer(renderer) {
    renderer.draw(baseRectangle);
  }
}

