function draw() {
  translate(-width / 2, -height / 2);
  background("#a5d6a5"); // Green color for the green hills

  brush.noStroke();

  // Painting sky
  brush.fill("skyblue");
  brush.beginShape(1);
  brush.vertex(0, 200);
  brush.vertex(width / 2, 300);
  brush.vertex(width, 200);
  brush.endShape(true);

  // Landscape
  brush.fill("#ff9c00"); // Orange-yellow (Goldenrod) color for the sand

  // Hills
  for (let i = width * 0.2; i < width; i += width * 0.2) {
    brush.beginShape(0.8);
    brush.vertex(i, height * 0.5);
    brush.vertex(i, height - (i - 0.5) * (height - (width * 0.2))) ;
    brush.vertex(width, height - (width - (i - 0.5)) * (height - (width * 0.2))); 
    brush.vertex(width, height * 0.5); 
    brush.endShape(true);
  }

  // Sand patches
  brush.noFill();
  brush.beginShape(0.3);
  brush.vertex(0, height * 0.4);
  brush.vertex(width, height * 0.4);
  brush.vertex(width * 0.7, height * 0.6);
  brush.vertex(0.3, height * 0.6);
  brush.endShape(true);

  // Coastline
  brush.noFill();
  brush.beginShape(0.5);
  brush.vertex(0, height - (height - (width * 0.2)));
  brush.vertex(width, height - (height - (width * 0.2)));
  brush.vertex(width / 2, height - (height - (width * 0.2) + 300));
  brush.vertex(0, height - (height - (width * 0.2) + 300));
  brush.endShape(true);
}

