  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("green");
  // darkening color gradually towards white in the clouds
  let cloudColor = "#1f81e6";
  let cloudOpacity = 255;
  for (let i = 10; i < width; i += 30) {
    let j = random(height * 0.5, height);
    cloudColor = lerp(cloudColor, "white", sin(frameCount / 500) * 0.1);
    cloudOpacity = map(sin(i / 25), -1, 1, 0, 255);
    brush.noFill();
    brush.fillBrightness(map(sin(i / 100), -1, 1, 0, 255));
    brush.fillBlend(0.6);
    brush.fillTexture(0.3, 0.4);
    brush.fill(cloudColor, cloudOpacity);
    brush.beginShape(0.3);
    brush.vertex(i, j);
    brush.vertex(i + random(10), j);
    brush.vertex(i + random(10), j + random(10));
    brush.vertex(i, j + random(10));
    brush.endShape(true);
  }

  // hill and sun
  brush.fill("#eee7da");
  brush.fillTexture(0.6, 0.4);
  brush.fill("#bcbdb9", 180);
  brush.beginShape(0.4);
  brush.vertex(width / 4, 0);
  brush.vertex(width, 0);
  brush.vertex(width, height / 2);
  brush.vertex(width / 4, height / 2);
  brush.endShape(true);
  brush.fill("#cdcdc8", 220);
  brush.circle(200, height / 2, 120);
}

