function setup() {
  createCanvas(800, 600, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#a8eae8");
  brush.noStroke();
  brush.texture("#aed1a4");  // Green hill texture
  brush.fill("#f4efe4");  // Sunset color
  brush.circle(200, 400, 200);  // Center of sun

  // Hills
  for (let i = -200; i <= 200; i += 50) {
    brush.noStroke();
    brush.texture("#a8eae8");  // Green hill texture
    brush.noFill();  // Black out the hill
    brush.circle(i + 40, 300, 250);
  }

  // Trees
  brush.fillStyle("#7b6857");  // Dark brown tree bark
  for (let j = -150; j < 150; j += 80) {
    brush.stroke("#867163");  // Brown trunk
    brush.fillRect(j, 300, 50, 50);
    brush.noStroke();
    brush.color("#fff");  // White leaves
    brush.fill(texture("#aed1a4"));  // Leaf vein texture
    brush.rotate(random(-PI/12, PI/12));
    brush.beginShape();
    brush.vertex(j - 30, 350);
    brush.vertex(j + 30, 350);
    brush.vertex(j + 10, 300);
    brush.endShape(false);
  }

  // Clouds
  for (let k = -100; k <= 300; k += 50) {
    brush.noStroke();
    brush.texture("#FFFFFF");  // Bright white cloud texture
    brush.fill("#fff");  // White clouds
    brush.circle(k + random(0, 20), 400, 30);
  }
}

